// 💠 DIAMANT VGT SUPREME STATUS
use crate::{engine::validate_policy_set,model::PolicySet,PolicyError};
use base64::{engine::general_purpose::STANDARD,Engine};
use ed25519_dalek::{Signature,Verifier,VerifyingKey};
use serde::{Deserialize,Serialize};
use sha2::{Digest,Sha256};

pub const POLICY_BUNDLE_SCHEMA:&str="vgt.workspace.policy-bundle/1";
#[derive(Debug,Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct PolicyBundlePayload{pub schema:String,pub bundle_id:String,pub issued_at_unix_ms:i64,pub policy:PolicySet}
#[derive(Debug,Clone,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct SignedPolicyBundle{pub payload:PolicyBundlePayload,pub public_key_base64:String,pub signature_base64:String}
impl SignedPolicyBundle{pub fn canonical_payload(&self)->Result<Vec<u8>,PolicyError>{serde_json::to_vec(&self.payload).map_err(|_|PolicyError::BundleInvalid)} pub fn verify(&self,pinned_fingerprint_hex:Option<&str>)->Result<PolicySet,PolicyError>{if self.payload.schema!=POLICY_BUNDLE_SCHEMA||self.payload.bundle_id.is_empty()||self.payload.bundle_id.len()>128{return Err(PolicyError::BundleInvalid);}validate_policy_set(&self.payload.policy)?;let pk=STANDARD.decode(&self.public_key_base64).map_err(|_|PolicyError::BundleSignature)?;let sig=STANDARD.decode(&self.signature_base64).map_err(|_|PolicyError::BundleSignature)?;let key=VerifyingKey::from_bytes(pk.as_slice().try_into().map_err(|_|PolicyError::BundleSignature)?).map_err(|_|PolicyError::BundleSignature)?;let signature=Signature::from_slice(&sig).map_err(|_|PolicyError::BundleSignature)?;key.verify(&self.canonical_payload()?,&signature).map_err(|_|PolicyError::BundleSignature)?;if let Some(pin)=pinned_fingerprint_hex{let mut h=Sha256::new();h.update(key.as_bytes());let got=format!("{:x}",h.finalize());if got!=pin{return Err(PolicyError::BundleSignerMismatch);}}Ok(self.payload.policy.clone())}}

impl SignedPolicyBundle{pub fn verify_enterprise_root(&self,pinned_fingerprint_hex:&str)->Result<PolicySet,PolicyError>{if pinned_fingerprint_hex.len()!=64||!pinned_fingerprint_hex.bytes().all(|b|b.is_ascii_hexdigit()){return Err(PolicyError::BundleSignerMismatch);}self.verify(Some(&pinned_fingerprint_hex.to_ascii_lowercase()))}}
pub fn strictest_fallback_policy()->PolicySet{use crate::model::{PolicyEffect,PolicyRule,PolicyScope,PolicyScopeKind,PolicyVersionState,POLICY_SCHEMA};PolicySet{schema:POLICY_SCHEMA.into(),policy_id:"enterprise-signature-fallback".into(),version:1,state:PolicyVersionState::Published,rollout_percent:100,rules:vec![PolicyRule{id:"deny-all-unverified-policy".into(),subject:"*".into(),resource:"*".into(),action:"*".into(),conditions:vec![],effect:PolicyEffect::Deny,priority:i32::MAX,scope:PolicyScope{kind:PolicyScopeKind::Machine,id:"signature-fallback".into()},rationale:"Unverified organization policy is ignored and replaced by strictest deny fallback".into(),reason_code:"POLICY_SIGNATURE_FAIL_CLOSED".into()}]}}
pub fn verify_enterprise_root_or_strictest(bundle:&SignedPolicyBundle,pinned_fingerprint_hex:&str)->(PolicySet,bool){match bundle.verify_enterprise_root(pinned_fingerprint_hex){Ok(policy)=>(policy,true),Err(_)=>(strictest_fallback_policy(),false)}}
